WEIGHTS = {'Anglo': 0.13, 'AfricanAmerican': 0.09, 'WestAfrican': 0.06, 'Latino': 0.1, 'Italian': 0.04, 'French': 0.05, 'German': 0.05, 'Nordic': 0.05, 'Slavic': 0.06, 'Japanese': 0.05, 'Korean': 0.04, 'Chinese': 0.05, 'SouthAsian': 0.07, 'Arabic': 0.06, 'Polynesian': 0.04, 'NativeAmerican': 0.03, 'Greek': 0.02, 'Roia': 0.072}
_BGS = list(WEIGHTS.keys())
_W = [WEIGHTS[b] for b in _BGS]

def pick_name(rng, used, want_bg=None, surname_usage=None, surname_cap=10):
    """Returns (full_name, first_bg, last_bg). 40/40/20 language pairing.
    surname_usage: optional Counter to cap how many players share one surname."""
    for _ in range(400):
        fb = want_bg or rng.choices(_BGS, weights=_W)[0]
        roll = rng.random()
        if roll < 0.40: lb = fb
        elif roll < 0.80:
            sims = SIMILAR.get(fb, [fb]); lb = rng.choice(sims) if sims else fb
        else: lb = rng.choices(_BGS, weights=_W)[0]
        last = rng.choice(BG[lb]["last"])
        if surname_usage is not None and surname_usage[last] >= surname_cap: continue
        full = rng.choice(BG[fb]["first"]) + " " + last
        if full not in used:
            used.add(full)
            if surname_usage is not None: surname_usage[last] += 1
            return full, fb, lb
    while True:
        fb = rng.choices(_BGS, weights=_W)[0]
        last = rng.choice(BG[fb]["last"])
        full = f'{rng.choice(BG[fb]["first"])} {chr(rng.randint(65,90))}. {rng.choice(BG[fb]["last"])}'
        if full not in used:
            used.add(full)
            if surname_usage is not None: surname_usage[last] += 1
            return full, fb, fb

