def _clean(parts):
    return [p for p in parts if "? no" not in p]

def gen_surname(bg, rng):
    stems, sufs = SURGEN.get(bg, SURGEN["Anglo"])
    stems = _clean(stems); sufs = _clean(sufs)
    if bg == "Arabic":
        return rng.choice(stems) + rng.choice(sufs)
    if bg == "Korean":
        for _ in range(20):
            st_, su_ = rng.choice(stems), rng.choice(sufs)
            if st_.lower() != su_.strip("-").lower():
                return st_ + su_
        return st_ + su_
    if bg == "Chinese":
        a = rng.choice(_clean(SURGEN["Chinese"][0]))
        b = rng.choice(SURGEN["Chinese"][1])
        return a + b
    s = rng.choice(stems) + rng.choice(sufs)
    # fix double letters at the seam for latin-script styles
    return s[0].upper() + s[1:]

def pick_name_v2(rng, used, want_bg=None, surname_usage=None, surname_cap=2, curated_p=0.30):
    """40/40/20 pairing with morphological surname generation for deep uniqueness.
    Returns (full_name, first_bg, last_bg)."""
    for _ in range(600):
        fb = want_bg or rng.choices(_BGS, weights=_W)[0]
        roll = rng.random()
        if roll < 0.40: lb = fb
        elif roll < 0.80:
            sims = SIMILAR.get(fb, [fb]); lb = rng.choice(sims) if sims else fb
        else: lb = rng.choices(_BGS, weights=_W)[0]
        if rng.random() < curated_p:
            last = rng.choice(BG[lb]["last"])
        else:
            last = gen_surname(lb, rng)
        if surname_usage is not None and surname_usage[last] >= surname_cap:
            continue
        full = rng.choice(BG[fb]["first"]) + " " + last
        if full not in used:
            used.add(full)
            if surname_usage is not None: surname_usage[last] += 1
            return full, fb, lb
    raise RuntimeError("name space exhausted")
